<?php $this->layout('default'); use Moves\Services\CmsQuery; use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; $agents = H::agents(); ?>
<div class="cms-card"><?php if ($agents === []): ?><?= V::empty('Nenhum atendente com permissão de responder.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Atendente</th><th>Papel</th><th class="num">Em aberto</th><th class="num">Resolvidos</th></tr></thead><tbody><?php foreach ($agents as $a): $uid = (int) $a['user_id']; ?><tr><td><a href="/chamados?assignee=<?= $uid ?>"><?= V::e(trim($a['first_name'] . ' ' . $a['last_name'])) ?></a></td><td><?= V::e($a['role_name']) ?></td><td class="num"><?= (int) CmsQuery::value("SELECT COUNT(*) FROM helpdesk_tickets WHERE assignee_user_id=? AND status NOT IN ('resolved','closed')", [$uid]) ?></td><td class="num"><?= (int) CmsQuery::value("SELECT COUNT(*) FROM helpdesk_tickets WHERE assignee_user_id=? AND status IN ('resolved','closed')", [$uid]) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
